import { Input } from '@refy-design/web';
import { ThemeProvider } from '@refy-design/web';
import type { ComponentProps } from 'react';
const SearchIcon = (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.8}
    strokeLinecap="round"
  >
    <circle cx="11" cy="11" r="7" />
    <path d="m21 21-4.3-4.3" />
  </svg>
);
export function Example() {
  const args: Pick<ComponentProps<typeof Input>, 'label' | 'placeholder' | 'block'> = {
    label: 'Workspace name',
    placeholder: 'Example team',
    block: true,
  };
  return (
    <ThemeProvider
      theme={{
        name: 'Search field',
        tokens: {
          '--input-prefix-color': 'var(--ink-4)',
          '--field-font-family': 'system-ui, sans-serif',
        },
      }}
    >
      <div data-testid="input-measures">
        <Input
          {...args}
          label="Search"
          prefix={SearchIcon}
          placeholder="Bikes, sofas, phones"
        />
      </div>
    </ThemeProvider>
  );
}
